INSERT INTO public.tours (id, title_en, title_ru, description_en, description_ru, price, base_price, extra_person_fee, price_per_person, duration, image, rating, category, highlights_en, highlights_ru, itinerary_en, itinerary_ru, route_stops, price_options, reviews, created_at) VALUES ('ai-gen-1768351311203-417', 'AI Trip: Kutaisi ➝ Kutaisi', 'AI Тур: Kutaisi ➝ Kutaisi', 'Насладитесь однодневной экскурсией из Кутаиси к уединенному водопаду Мецкера и священной горе Цхраджвари с панорамными видами. Откройте для себя нетронутую природу и духовные места Грузии, завершив путешествие возвращением в Кутаиси.', 'Насладитесь однодневной экскурсией из Кутаиси к уединенному водопаду Мецкера и священной горе Цхраджвари с панорамными видами. Откройте для себя нетронутую природу и духовные места Грузии, завершив путешествие возвращением в Кутаиси.', 'From 324 GEL', 324, 0, 0, '6h 0m', 'https://image.pollinations.ai/prompt/A%20photorealistic%2C%20cinematic%20travel%20photo%20of%20%D0%92%D0%BE%D0%B4%D0%BE%D0%BF%D0%B0%D0%B4%20%D0%9C%D0%B5%D1%86%D0%BA%D0%B5%D1%80%D0%B0%2C%20professional%20photography%2C%204k%20%2C%20realistic%2C%208k%2C%20georgia%20travel?width=1280&height=720&model=flux&nologo=true&seed=10785', 5, 'AI_UNIQUE', '["Kutaisi","Водопад Мецкера","Гора Цхраджвари","Кутаиси","Kutaisi"]', '["Kutaisi","Водопад Мецкера","Гора Цхраджвари","Кутаиси","Kutaisi"]', '["Visit Kutaisi: Начало вашего путешествия по менее изведанным местам Грузии, отправная точка для открытия скрытых природных красот.","Visit Водопад Мецкера: Водопад Мецкера — это настоящая скрытая жемчужина природы, расположенная в живописной местности недалеко от Кутаиси. Это идеальное место для тех, кто ищет уединения и покоя вдали от шумных туристических маршрутов, желая открыть для себя аутентичную красоту Грузии. Здесь вы сможете насладиться нетронутой красотой грузинской природы, где вода мягко каскадом стекает по мшистым скалам, создавая освежающий туман и мелодичный, умиротворяющий звук, который помогает забыть о городской суете. Густые леса вокруг водопада предлагают прохладу и чистоту воздуха, приглашая к неспешным прогулкам, медитации и созерцанию. Место не так популярно среди массовых туристов, что позволяет по-настоящему погрузиться в атмосферу дикой природы и почувствовать себя наедине с ней, наслаждаясь каждым моментом. Это отличная возможность сделать уникальные фотографии потрясающих пейзажей и создать незабываемые воспоминания о вашей экскурсии, оставив позади привычные проторенные тропы.","Visit Гора Цхраджвари: Гора Цхраджвари, что в переводе означает «Девять Крестов», является священным и живописным местом, откуда открываются захватывающие панорамные виды на окружающие долины и величественные горные хребты. Это идеальное место для легкого треккинга и наслаждения чистейшим горным воздухом. На вершине горы расположены древние кресты, которые придают месту особую атмосферу духовности и загадочности, делая его важным паломническим центром для местных жителей. Считается, что гора обладает мистической силой, и посещение её может принести умиротворение и вдохновение. Подъем на гору вознаграждается потрясающими пейзажами, которые особенно впечатляюще выглядят на закате или восходе солнца, когда небо окрашивается в невероятные цвета. Это отличный выбор для любителей природы, фотографии и тех, кто ищет глубоких впечатлений, исследуя менее известные, но невероятно красивые уголки Грузии.","Visit Кутаиси: Return trip.","Visit Kutaisi: Возвращение"]', '["Посещение Kutaisi: Начало вашего путешествия по менее изведанным местам Грузии, отправная точка для открытия скрытых природных красот.","Посещение Водопад Мецкера: Водопад Мецкера — это настоящая скрытая жемчужина природы, расположенная в живописной местности недалеко от Кутаиси. Это идеальное место для тех, кто ищет уединения и покоя вдали от шумных туристических маршрутов, желая открыть для себя аутентичную красоту Грузии. Здесь вы сможете насладиться нетронутой красотой грузинской природы, где вода мягко каскадом стекает по мшистым скалам, создавая освежающий туман и мелодичный, умиротворяющий звук, который помогает забыть о городской суете. Густые леса вокруг водопада предлагают прохладу и чистоту воздуха, приглашая к неспешным прогулкам, медитации и созерцанию. Место не так популярно среди массовых туристов, что позволяет по-настоящему погрузиться в атмосферу дикой природы и почувствовать себя наедине с ней, наслаждаясь каждым моментом. Это отличная возможность сделать уникальные фотографии потрясающих пейзажей и создать незабываемые воспоминания о вашей экскурсии, оставив позади привычные проторенные тропы.","Посещение Гора Цхраджвари: Гора Цхраджвари, что в переводе означает «Девять Крестов», является священным и живописным местом, откуда открываются захватывающие панорамные виды на окружающие долины и величественные горные хребты. Это идеальное место для легкого треккинга и наслаждения чистейшим горным воздухом. На вершине горы расположены древние кресты, которые придают месту особую атмосферу духовности и загадочности, делая его важным паломническим центром для местных жителей. Считается, что гора обладает мистической силой, и посещение её может принести умиротворение и вдохновение. Подъем на гору вознаграждается потрясающими пейзажами, которые особенно впечатляюще выглядят на закате или восходе солнца, когда небо окрашивается в невероятные цвета. Это отличный выбор для любителей природы, фотографии и тех, кто ищет глубоких впечатлений, исследуя менее известные, но невероятно красивые уголки Грузии.","Посещение Кутаиси: Return trip.","Посещение Kutaisi: Возвращение"]', '["Kutaisi","Водопад Мецкера","Гора Цхраджвари","Кутаиси","Kutaisi"]', '[{"price":"324 GEL","guests":"1-4","vehicle":"Sedan"},{"price":"454 GEL","guests":"5-7","vehicle":"Minivan"},{"price":"713 GEL","guests":"8+","vehicle":"Bus"}]', '[]', '2026-01-14T00:41:51.694141+00:00');
