INSERT INTO public.tours (id, title_en, title_ru, description_en, description_ru, price, base_price, extra_person_fee, price_per_person, duration, image, rating, category, highlights_en, highlights_ru, itinerary_en, itinerary_ru, route_stops, price_options, reviews, created_at) VALUES ('ai-gen-1768359067699-164', 'AI Trip: Kutaisi ➝ Kutaisi', 'AI Тур: Kutaisi ➝ Kutaisi', 'A delightful culinary journey from Kutaisi to Baia''s Wine, offering authentic Georgian village food, organic wines, and warm family hospitality.', 'A delightful culinary journey from Kutaisi to Baia''s Wine, offering authentic Georgian village food, organic wines, and warm family hospitality.', 'From 126 GEL', 126, 0, 0, '1 hour 30 minutes', 'https://image.pollinations.ai/prompt/A%20photorealistic%2C%20cinematic%20travel%20photo%20of%20Baia''s%20Wine%2C%20professional%20photography%2C%204k%20%2C%20realistic%2C%208k%2C%20georgia%20travel?width=1280&height=720&model=flux&nologo=true&seed=76504', 5, 'AI_UNIQUE', '["Kutaisi","Baia's Wine","Kutaisi"]', '["Kutaisi","Baia's Wine","Kutaisi"]', '["Visit Kutaisi: Begin your culinary adventure from the historical city of Kutaisi, exploring its charming streets before heading out to the Imereti region's countryside.","Visit Baia's Wine: Your main stop is Baia's Wine, a renowned family winery nestled in Meore Obcha, Bagdati. This location perfectly encapsulates the 'Village food', 'Family kitchen', and 'Homemade wine' wishes, offering natural and organic wines crafted with traditional Georgian methods [33]. Visitors can indulge in authentic local dishes, enjoy wine tastings, and learn about organic farming practices in a serene, pastoral setting. While not explicitly mentioned for 'Best Khinkali' in the search results, traditional Georgian eateries and wineries often serve a variety of local specialties that showcase the rich culinary heritage of the region.","Visit Kutaisi: Conclude your gourmet excursion back in Kutaisi, filled with the delightful tastes and memories of authentic Georgian hospitality and cuisine."]', '["Посещение Kutaisi: Begin your culinary adventure from the historical city of Kutaisi, exploring its charming streets before heading out to the Imereti region's countryside.","Посещение Baia's Wine: Your main stop is Baia's Wine, a renowned family winery nestled in Meore Obcha, Bagdati. This location perfectly encapsulates the 'Village food', 'Family kitchen', and 'Homemade wine' wishes, offering natural and organic wines crafted with traditional Georgian methods [33]. Visitors can indulge in authentic local dishes, enjoy wine tastings, and learn about organic farming practices in a serene, pastoral setting. While not explicitly mentioned for 'Best Khinkali' in the search results, traditional Georgian eateries and wineries often serve a variety of local specialties that showcase the rich culinary heritage of the region.","Посещение Kutaisi: Conclude your gourmet excursion back in Kutaisi, filled with the delightful tastes and memories of authentic Georgian hospitality and cuisine."]', '["Kutaisi","Baia's Wine","Kutaisi"]', '[{"price":"126 GEL","guests":"1-4","vehicle":"Sedan"},{"price":"177 GEL","guests":"5-7","vehicle":"Minivan"},{"price":"278 GEL","guests":"8+","vehicle":"Bus"}]', '[]', '2026-01-14T02:51:08.437673+00:00');
INSERT INTO public.tours (id, title_en, title_ru, description_en, description_ru, price, base_price, extra_person_fee, price_per_person, duration, image, rating, category, highlights_en, highlights_ru, itinerary_en, itinerary_ru, route_stops, price_options, reviews, created_at) VALUES ('ai-gen-1768359201125-680', 'AI Trip: Kutaisi ➝ Kutaisi', 'AI Тур: Kutaisi ➝ Kutaisi', 'Классический маршрут (AI Offline).', 'Классический маршрут (AI Offline).', 'From 234 GEL', 234, 0, 0, '5-6 Hours', 'https://image.pollinations.ai/prompt/A%20photorealistic%2C%20cinematic%20travel%20photo%20of%20%D0%9F%D0%B5%D1%89%D0%B5%D1%80%D0%B0%20%D0%9F%D1%80%D0%BE%D0%BC%D0%B5%D1%82%D0%B5%D1%8F%2C%20professional%20photography%2C%204k%20%2C%20realistic%2C%208k%2C%20georgia%20travel?width=1280&height=720&model=flux&nologo=true&seed=53858', 5, 'AI_UNIQUE', '["Kutaisi","Пещера Прометея","Каньон Мартвили","Кутаиси (Финиш)","Kutaisi"]', '["Kutaisi","Пещера Прометея","Каньон Мартвили","Кутаиси (Финиш)","Kutaisi"]', '["Visit Kutaisi: Start.","Visit Пещера Прометея: Cave.","Visit Каньон Мартвили: Canyon.","Visit Кутаиси (Финиш): Finish.","Visit Kutaisi: Возвращение"]', '["Посещение Kutaisi: Start.","Посещение Пещера Прометея: Cave.","Посещение Каньон Мартвили: Canyon.","Посещение Кутаиси (Финиш): Finish.","Посещение Kutaisi: Возвращение"]', '["Kutaisi","Пещера Прометея","Каньон Мартвили","Кутаиси (Финиш)","Kutaisi"]', '[{"price":"234 GEL","guests":"1-4","vehicle":"Sedan"},{"price":"328 GEL","guests":"5-7","vehicle":"Minivan"},{"price":"515 GEL","guests":"8+","vehicle":"Bus"}]', '[]', '2026-01-14T02:53:21.769562+00:00');
INSERT INTO public.tours (id, title_en, title_ru, description_en, description_ru, price, base_price, extra_person_fee, price_per_person, duration, image, rating, category, highlights_en, highlights_ru, itinerary_en, itinerary_ru, route_stops, price_options, reviews, created_at) VALUES ('ai-gen-1768396012240-493', 'AI Trip: Kutaisi ➝ Kutaisi', 'AI Тур: Kutaisi ➝ Kutaisi', 'This driving route takes you from Kutaisi to the most accessible trailhead for the Tobavarchkhili Lakes. Please remember that the journey to the lakes themselves is a challenging multi-day trek requiring thorough preparation. This route outlines the driving portion of your unforgettable adventure into Georgia''s pristine high mountains.', 'This driving route takes you from Kutaisi to the most accessible trailhead for the Tobavarchkhili Lakes. Please remember that the journey to the lakes themselves is a challenging multi-day trek requiring thorough preparation. This route outlines the driving portion of your unforgettable adventure into Georgia''s pristine high mountains.', 'From 282 GEL', 282, 0, 0, '5h 30 min', 'https://image.pollinations.ai/prompt/A%20photorealistic%2C%20cinematic%20travel%20photo%20of%20Tobavarchkhili%20Lakes%20Trailhead%20(Near%20Mukhuri)%2C%20professional%20photography%2C%204k%20%2C%20realistic%2C%208k%2C%20georgia%20travel?width=1280&height=720&model=flux&nologo=true&seed=99764', 5, 'AI_UNIQUE', '["Kutaisi","Tobavarchkhili Lakes Trailhead (Near Mukhuri)","Kutaisi"]', '["Kutaisi","Tobavarchkhili Lakes Trailhead (Near Mukhuri)","Kutaisi"]', '["Visit Kutaisi: Start your incredible adventure from Kutaisi, the heart of Imereti region. As one of Georgia's oldest cities, Kutaisi boasts rich history, including the UNESCO World Heritage Sites of Bagrati Cathedral and Gelati Monastery, providing a cultural prelude to your wilderness expedition.","Visit Tobavarchkhili Lakes Trailhead (Near Mukhuri): This point marks the practical end of the drivable road for most vehicles on the approach to the legendary Tobavarchkhili Lakes. Nestled deep within the Egrisi Mountains, the 'Silver Lakes' (as Tobavarchkhili translates) are a cluster of stunning alpine lakes renowned for their pristine beauty and challenging accessibility. From here, the true adventure begins. The journey to the actual lakes transforms into a multi-day trekking expedition, typically ranging from 3 to 5 days, requiring proper hiking gear, experienced local guides, and excellent physical condition. The trek often involves navigating diverse terrain, including lush sub-tropical forests, vast alpine meadows, and rocky passes, often crossing high mountain ridges. Adventurers are rewarded with breathtaking panoramas, incredibly clear waters, and the serene majesty of the remote Georgian wilderness, making it an unforgettable experience for seasoned hikers seeking Georgia's wild heart.","Visit Kutaisi: Conclude your driving journey back in Kutaisi, filled with memories of the stunning landscapes and the anticipation or triumph of your trek to the remote Tobavarchkhili Lakes."]', '["Посещение Kutaisi: Start your incredible adventure from Kutaisi, the heart of Imereti region. As one of Georgia's oldest cities, Kutaisi boasts rich history, including the UNESCO World Heritage Sites of Bagrati Cathedral and Gelati Monastery, providing a cultural prelude to your wilderness expedition.","Посещение Tobavarchkhili Lakes Trailhead (Near Mukhuri): This point marks the practical end of the drivable road for most vehicles on the approach to the legendary Tobavarchkhili Lakes. Nestled deep within the Egrisi Mountains, the 'Silver Lakes' (as Tobavarchkhili translates) are a cluster of stunning alpine lakes renowned for their pristine beauty and challenging accessibility. From here, the true adventure begins. The journey to the actual lakes transforms into a multi-day trekking expedition, typically ranging from 3 to 5 days, requiring proper hiking gear, experienced local guides, and excellent physical condition. The trek often involves navigating diverse terrain, including lush sub-tropical forests, vast alpine meadows, and rocky passes, often crossing high mountain ridges. Adventurers are rewarded with breathtaking panoramas, incredibly clear waters, and the serene majesty of the remote Georgian wilderness, making it an unforgettable experience for seasoned hikers seeking Georgia's wild heart.","Посещение Kutaisi: Conclude your driving journey back in Kutaisi, filled with memories of the stunning landscapes and the anticipation or triumph of your trek to the remote Tobavarchkhili Lakes."]', '["Kutaisi","Tobavarchkhili Lakes Trailhead (Near Mukhuri)","Kutaisi"]', '[{"price":"282 GEL","guests":"1-4","vehicle":"Sedan"},{"price":"395 GEL","guests":"5-7","vehicle":"Minivan"},{"price":"621 GEL","guests":"8+","vehicle":"Bus"}]', '[]', '2026-01-14T13:06:53.13342+00:00');
INSERT INTO public.tours (id, title_en, title_ru, description_en, description_ru, price, base_price, extra_person_fee, price_per_person, duration, image, rating, category, highlights_en, highlights_ru, itinerary_en, itinerary_ru, route_stops, price_options, reviews, created_at) VALUES ('ai-gen-1768438562064-584', 'AI Trip: Tbilisi ➝ Tbilisi', 'AI Тур: Tbilisi ➝ Tbilisi', 'Embark on a captivating road trip from Tbilisi, delving into Georgia''s renowned Kakheti region. This route offers a delightful blend of culture, history, and culinary experiences, starting with the charming ''City of Love'' Sighnaghi for its panoramic views and wine cellars. Continue to Telavi, the historical heart of Kakheti, to explore royal fortresses, museums, and more esteemed wineries. Throughout the journey, discover numerous opportunities for indoor activities and savor delicious cuisine at cozy local restaurants, before returning to the vibrant capital, Tbilisi.', 'Embark on a captivating road trip from Tbilisi, delving into Georgia''s renowned Kakheti region. This route offers a delightful blend of culture, history, and culinary experiences, starting with the charming ''City of Love'' Sighnaghi for its panoramic views and wine cellars. Continue to Telavi, the historical heart of Kakheti, to explore royal fortresses, museums, and more esteemed wineries. Throughout the journey, discover numerous opportunities for indoor activities and savor delicious cuisine at cozy local restaurants, before returning to the vibrant capital, Tbilisi.', 'From 348 GEL', 348, 0, 0, '4h 40min', 'https://image.pollinations.ai/prompt/A%20photorealistic%2C%20cinematic%20travel%20photo%20of%20Sighnaghi%2C%20professional%20photography%2C%204k%20%2C%20realistic%2C%208k%2C%20georgia%20travel?width=1280&height=720&model=flux&nologo=true&seed=52972', 5, 'AI_UNIQUE', '["Tbilisi","Sighnaghi","Telavi","Tbilisi"]', '["Tbilisi","Sighnaghi","Telavi","Tbilisi"]', '["Visit Tbilisi: Start your captivating journey from Tbilisi, the vibrant capital of Georgia. This historic city, nestled in the Mtkvari River valley, boasts a rich tapestry of ancient churches, bustling flea markets, and a burgeoning contemporary art scene. Before heading out, you might explore the Georgian National Museum for its extensive collections or enjoy a traditional Georgian meal at a cozy restaurant in the Old Town. Tbilisi serves as the perfect launchpad for your exploration into the diverse landscapes and cultural treasures of the country.","Visit Sighnaghi: Your first stop is Sighnaghi, often affectionately called the 'City of Love,' renowned for its charming cobblestone streets and well-preserved defensive walls that encircle the town. These walls offer breathtaking panoramic views of the vast Alazani Valley and the majestic Greater Caucasus Mountains. Sighnaghi is a prominent gateway to the Kakheti wine region, making it an ideal destination for those eager to explore wine cellars. Visitors can indulge in traditional qvevri wine tastings at local family-run wineries and savor authentic Georgian cuisine in its many cozy restaurants. The Sighnaghi Museum provides an enriching indoor activity, showcasing archaeological finds and works by the famous Georgian artist Niko Pirosmani. A short detour to the nearby Bodbe Monastery, an important pilgrimage site with beautiful frescoes, adds a serene cultural and historical dimension to your visit.","Visit Telavi: Continue your journey to Telavi, the historical capital of Kakheti, a city that masterfully blends royal history with the heart of Georgian winemaking. The centerpiece of Telavi is the impressive Batonis Tsikhe fortress, which houses King Erekle II's Palace and an engaging Telavi Historical Museum, offering excellent indoor cultural exploration into the region's royal past. The city's vibrant local market is perfect for discovering regional produce and crafts, while numerous cozy restaurants invite you to savor traditional dishes. Telavi is surrounded by a multitude of renowned wineries, from grand estates to intimate family vineyards, making it a prime location for comprehensive wine cellar tours and tastings. Nearby, the ancient Alaverdi Monastery and the peaceful Shuamta Monasteries offer architectural grandeur and serene natural beauty, providing further cultural depth to your exploration of Kakheti's rich heritage.","Visit Tbilisi: Conclude your memorable Kakheti journey by returning to the bustling capital, Tbilisi. This final leg of your trip offers a chance to reflect on the rich history, exquisite wines, and warm hospitality you've experienced throughout your road trip. Upon your return, Tbilisi provides a final opportunity for souvenir shopping in its unique boutiques, visiting any remaining museums you might have missed, or enjoying a celebratory farewell dinner at one of its many celebrated restaurants, bringing your Georgian adventure to a perfect close."]', '["Посещение Tbilisi: Start your captivating journey from Tbilisi, the vibrant capital of Georgia. This historic city, nestled in the Mtkvari River valley, boasts a rich tapestry of ancient churches, bustling flea markets, and a burgeoning contemporary art scene. Before heading out, you might explore the Georgian National Museum for its extensive collections or enjoy a traditional Georgian meal at a cozy restaurant in the Old Town. Tbilisi serves as the perfect launchpad for your exploration into the diverse landscapes and cultural treasures of the country.","Посещение Sighnaghi: Your first stop is Sighnaghi, often affectionately called the 'City of Love,' renowned for its charming cobblestone streets and well-preserved defensive walls that encircle the town. These walls offer breathtaking panoramic views of the vast Alazani Valley and the majestic Greater Caucasus Mountains. Sighnaghi is a prominent gateway to the Kakheti wine region, making it an ideal destination for those eager to explore wine cellars. Visitors can indulge in traditional qvevri wine tastings at local family-run wineries and savor authentic Georgian cuisine in its many cozy restaurants. The Sighnaghi Museum provides an enriching indoor activity, showcasing archaeological finds and works by the famous Georgian artist Niko Pirosmani. A short detour to the nearby Bodbe Monastery, an important pilgrimage site with beautiful frescoes, adds a serene cultural and historical dimension to your visit.","Посещение Telavi: Continue your journey to Telavi, the historical capital of Kakheti, a city that masterfully blends royal history with the heart of Georgian winemaking. The centerpiece of Telavi is the impressive Batonis Tsikhe fortress, which houses King Erekle II's Palace and an engaging Telavi Historical Museum, offering excellent indoor cultural exploration into the region's royal past. The city's vibrant local market is perfect for discovering regional produce and crafts, while numerous cozy restaurants invite you to savor traditional dishes. Telavi is surrounded by a multitude of renowned wineries, from grand estates to intimate family vineyards, making it a prime location for comprehensive wine cellar tours and tastings. Nearby, the ancient Alaverdi Monastery and the peaceful Shuamta Monasteries offer architectural grandeur and serene natural beauty, providing further cultural depth to your exploration of Kakheti's rich heritage.","Посещение Tbilisi: Conclude your memorable Kakheti journey by returning to the bustling capital, Tbilisi. This final leg of your trip offers a chance to reflect on the rich history, exquisite wines, and warm hospitality you've experienced throughout your road trip. Upon your return, Tbilisi provides a final opportunity for souvenir shopping in its unique boutiques, visiting any remaining museums you might have missed, or enjoying a celebratory farewell dinner at one of its many celebrated restaurants, bringing your Georgian adventure to a perfect close."]', '["Tbilisi","Sighnaghi","Telavi","Tbilisi"]', '[{"price":"348 GEL","guests":"1-4","vehicle":"Sedan"},{"price":"488 GEL","guests":"5-7","vehicle":"Minivan"},{"price":"766 GEL","guests":"8+","vehicle":"Bus"}]', '[]', '2026-01-15T00:56:03.023707+00:00');
