INSERT INTO public.tours (id, title_en, title_ru, description_en, description_ru, price, base_price, extra_person_fee, price_per_person, duration, image, rating, category, highlights_en, highlights_ru, itinerary_en, itinerary_ru, route_stops, price_options, reviews, created_at) VALUES ('ai-gen-1768443871064-734', 'AI Trip: Tbilisi ➝ Tbilisi', 'AI Тур: Tbilisi ➝ Tbilisi', 'Этот романтический маршрут начинается в Тбилиси и ведет в живописный город Сигнаги, известный как «Город любви». Вы сможете насладиться захватывающими закатами со Стены Сигнаги и завершить вечер вкусным ужином с грузинским вином на винодельне Pheasant''s Tears, прежде чем вернуться в Тбилиси.', 'Этот романтический маршрут начинается в Тбилиси и ведет в живописный город Сигнаги, известный как «Город любви». Вы сможете насладиться захватывающими закатами со Стены Сигнаги и завершить вечер вкусным ужином с грузинским вином на винодельне Pheasant''s Tears, прежде чем вернуться в Тбилиси.', 'From 366 GEL', 366, 0, 0, '3 Hours 35 Minutes', 'https://image.pollinations.ai/prompt/A%20photorealistic%2C%20cinematic%20travel%20photo%20of%20%D0%A1%D1%82%D0%B5%D0%BD%D0%B0%20%D0%A1%D0%B8%D0%B3%D0%BD%D0%B0%D0%B3%D0%B8%2C%20professional%20photography%2C%204k%20%2C%20realistic%2C%208k%2C%20georgia%20travel?width=1280&height=720&model=flux&nologo=true&seed=55903', 5, 'AI_UNIQUE', '["Tbilisi","Стена Сигнаги","Винодельня Pheasant's Tears","Тбилиси","Tbilisi"]', '["Tbilisi","Стена Сигнаги","Винодельня Pheasant's Tears","Тбилиси","Tbilisi"]', '["Visit Tbilisi: Начало вашего романтического путешествия из столицы Грузии, Тбилиси.","Visit Стена Сигнаги: Сигнаги, часто называемый «Городом любви», предлагает захватывающие панорамные виды на Алазанскую долину и Большой Кавказский хребет. Древняя Стена Сигнаги, часть городских укреплений, предоставляет несколько смотровых площадок, идеальных для романтических прогулок и наблюдения за spectacular закатами. Историческая атмосфера в сочетании с природной красотой делает это место идеальным для пар. [0]","Visit Винодельня Pheasant's Tears: Винодельня Pheasant's Tears известна своими традиционными грузинскими винами, ферментированными в квеври. Помимо дегустации вин, винодельня располагает двумя ресторанами, предлагающими восхитительные кулинарные впечатления с местными блюдами. Ее очаровательная атмосфера и акцент на аутентичные грузинские вкусы делают ее идеальным выбором для приятного романтического ужина в Сигнаги. [1]","Visit Тбилиси: Завершение вашего романтического маршрута обратно в Тбилиси.","Visit Tbilisi: Возвращение"]', '["Посещение Tbilisi: Начало вашего романтического путешествия из столицы Грузии, Тбилиси.","Посещение Стена Сигнаги: Сигнаги, часто называемый «Городом любви», предлагает захватывающие панорамные виды на Алазанскую долину и Большой Кавказский хребет. Древняя Стена Сигнаги, часть городских укреплений, предоставляет несколько смотровых площадок, идеальных для романтических прогулок и наблюдения за spectacular закатами. Историческая атмосфера в сочетании с природной красотой делает это место идеальным для пар. [0]","Посещение Винодельня Pheasant's Tears: Винодельня Pheasant's Tears известна своими традиционными грузинскими винами, ферментированными в квеври. Помимо дегустации вин, винодельня располагает двумя ресторанами, предлагающими восхитительные кулинарные впечатления с местными блюдами. Ее очаровательная атмосфера и акцент на аутентичные грузинские вкусы делают ее идеальным выбором для приятного романтического ужина в Сигнаги. [1]","Посещение Тбилиси: Завершение вашего романтического маршрута обратно в Тбилиси.","Посещение Tbilisi: Возвращение"]', '["Tbilisi","Стена Сигнаги","Винодельня Pheasant's Tears","Тбилиси","Tbilisi"]', '[{"price":"366 GEL","guests":"1-4","vehicle":"Sedan"},{"price":"513 GEL","guests":"5-7","vehicle":"Minivan"},{"price":"806 GEL","guests":"8+","vehicle":"Bus"}]', '[]', '2026-01-15T02:24:31.983561+00:00');
